import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;

    public static long power(int a, int b) {
        long ans = 1;
        while (b > 0) {
            ans = (ans * a) % MOD;
            b--;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        if (k == 0) {
            System.out.println(power(p, p - 1));
        } else if (k == 1) {
            System.out.println(power(p, p));
        } else {
            int ord = 1;
            int cur = k;
            while (cur != 1) {
                cur = (int) ((long) cur * k % p);
                ord++;
            }
            System.out.println(power(p, (p - 1) / ord));
        }
        sc.close();
    }
}
